# Look for any files mentioning endpoints / service contracts
import re
keys = ["PUT", "GET", "/v1", "epoch", "quorum", "commit_index", "apply_index", "leader", "fault", "inject"]
findings = {}
for root, dirs, files in os.walk("."):
    dirs[:] = [d for d in dirs if d not in {"__pycache__", "node_modules", ".git", ".cache", ".ipython"}]
    for fn in files:
        p = os.path.join(root, fn)
        if os.path.getsize(p) > 5_000_000:
            continue
        try:
            with open(p, "r", errors="ignore") as f:
                txt = f.read()
        except Exception:
            continue
        hits = [k for k in keys if k.lower() in txt.lower()]
        if hits:
            findings[p] = hits

print("\nfiles mentioning service/endpoint keywords:")
for p, h in findings.items():
    print(" ", p, "->", h)
if not findings:
    print("  (none)")
